import{_ as o,o as t,c as r,a6 as n}from"./chunks/framework.COmIsZrZ.js";const d=JSON.parse('{"title":"娲术基因序列 (Nuwa Genetics Sequence)","description":"","frontmatter":{"readingTime":"8 min read"},"headers":[],"relativePath":"项目实践/JRPG/A_角色与成长/角色升级/娲术基因序列/娲术基因序列.md","filePath":"项目实践/JRPG/A_角色与成长/角色升级/娲术基因序列/娲术基因序列.md"}'),i={name:"项目实践/JRPG/A_角色与成长/角色升级/娲术基因序列/娲术基因序列.md"};function e(s,l,a,g,u,h){return t(),r("div",null,[...l[0]||(l[0]=[n('<h1 id="娲术基因序列-nuwa-genetics-sequence" tabindex="-1">娲术基因序列 (Nuwa Genetics Sequence) <a class="header-anchor" href="#娲术基因序列-nuwa-genetics-sequence" aria-label="Permalink to &quot;娲术基因序列 (Nuwa Genetics Sequence)&quot;">​</a></h1><blockquote><p><strong>核心逻辑索引</strong>：有关角色属性如何聚合（等级+基因+装备）以及如何影响战斗的详细公式，请参阅 <strong><a href="./../../成长与战斗核心逻辑.html">成长与战斗核心逻辑</a></strong>。</p></blockquote><h2 id="_1-系统概述" tabindex="-1">1. 系统概述 <a class="header-anchor" href="#_1-系统概述" aria-label="Permalink to &quot;1. 系统概述&quot;">​</a></h2><p><strong>娲术基因序列</strong>是《神遗：蒸汽妖都》的核心角色成长系统之一，它结合了<strong>上古女娲神话</strong>与<strong>蒸汽生物科技</strong>。 不同于传统的线性天赋树，本系统采用<strong>双螺旋DNA图谱</strong>作为视觉载体，允许玩家通过“编辑”角色的基因链，来决定角色的进化方向（战斗风格、被动特性、环境交互能力）。</p><blockquote><p><strong>设定背景</strong>： “娲术”原本是女娲用于补天（实为基因编辑以适应恶劣环境）的神技。主角团利用周王室遗留的“娲术残篇”和现代蒸汽科技，制造出了便携式的**“灵枢解析仪”**，能够可视化并重构人体的隐性基因序列。</p></blockquote><hr><h2 id="_2-视觉交互设计-ui-ux" tabindex="-1">2. 视觉交互设计 (UI/UX) <a class="header-anchor" href="#_2-视觉交互设计-ui-ux" aria-label="Permalink to &quot;2. 视觉交互设计 (UI/UX)&quot;">​</a></h2><ul><li><p><strong>核心隐喻</strong>：<strong>双螺旋 DNA 链</strong> + <strong>中医经络图</strong>。</p></li><li><p><strong>界面表现</strong>：</p><ul><li>画面中央是一条缓缓旋转的全息 DNA 长链，链条由发光的“碱基对”（节点）连接。</li><li>背景是蒸汽风格的仪表盘和显微镜刻度，随着数值变化会有机械齿轮转动。</li><li><strong>色彩编码</strong>： <ul><li><strong>红色 (Red)</strong>：血肉/力量/体质（源自血族研究）</li><li><strong>蓝色 (Blue)</strong>：神经/反应/灵巧（源自电学刺激）</li><li><strong>金色 (Gold)</strong>：灵枢/精神/异能（源自娲石共鸣）</li><li><strong>紫色 (Purple)</strong>：变异/特殊效果（源自妖兽基因）</li></ul></li></ul></li><li><p><strong>操作方式</strong>：</p><ul><li><strong>旋转与缩放</strong>：玩家可以360度旋转 DNA 链，寻找未解锁的节点。</li><li><strong>注入</strong>：长按节点，会有注射器注入血清的动画，节点随之点亮并激活邻近路径。</li></ul></li></ul><hr><h2 id="_3-核心玩法机制" tabindex="-1">3. 核心玩法机制 <a class="header-anchor" href="#_3-核心玩法机制" aria-label="Permalink to &quot;3. 核心玩法机制&quot;">​</a></h2><h3 id="_3-1-序列节点-sequence-nodes" tabindex="-1">3.1. 序列节点 (Sequence Nodes) <a class="header-anchor" href="#_3-1-序列节点-sequence-nodes" aria-label="Permalink to &quot;3.1. 序列节点 (Sequence Nodes)&quot;">​</a></h3><p>DNA 链由无数个节点组成，分为三种类型：</p><ol><li><p><strong>基础碱基 (Base Node)</strong></p><ul><li><strong>作用</strong>：提供微量的基础属性加成（如：力量+2，暴击率+1%）。</li><li><strong>消耗</strong>：<strong>娲石能量 (Nuwa Energy)</strong>。 <ul><li><em>注：娲石能量与角色经验(XP)独立。XP提升等级，娲石能量用于基因点亮。</em></li></ul></li><li><strong>形态</strong>：小的发光点。</li></ul></li><li><p><strong>显性基因 (Dominant Gene)</strong></p><ul><li><strong>作用</strong>：<strong>技能系统的核心入口</strong>。解锁新的主动技能或改变技能形态（如：陈少秋的“电击”变为“链状闪电”）。</li><li><strong>消耗</strong>：<strong>娲石能量</strong> + <strong>特定生物样本</strong>（如：雷兽的腺体）。</li><li><strong>形态</strong>：大的六边形节点，有点亮特效。</li></ul></li><li><p><strong>隐性突变 (Recessive Mutation)</strong></p><ul><li><strong>作用</strong>：提供强大的被动效果，但通常伴随负面代价（<strong>副作用机制</strong>）。</li><li><strong>例子</strong>： <ul><li><em>狂暴之心</em>：物理攻击力 +30%，但每回合损失 5% 生命值。</li><li><em>铜皮铁骨</em>：防御力 +50%，但速度 -20%。</li></ul></li><li><strong>形态</strong>：带刺的紫色节点。</li></ul></li></ol><h3 id="_3-2-基因插槽与样本融合-gene-slots-fusion" tabindex="-1">3.2. 基因插槽与样本融合 (Gene Slots &amp; Fusion) <a class="header-anchor" href="#_3-2-基因插槽与样本融合-gene-slots-fusion" aria-label="Permalink to &quot;3.2. 基因插槽与样本融合 (Gene Slots &amp; Fusion)&quot;">​</a></h3><p>DNA 链上存在空的**“基因插槽”<strong>。玩家可以将从敌人身上收集到的</strong>“怪物基因样本”**插入这些插槽中。</p><ul><li><p><strong>收集玩法</strong>：</p><ul><li>击败特定的妖兽或血族精英后，使用主角朱利安的“采集”技能或战斗结算，可获得【未鉴定的基因片段】。</li><li>在安全屋（陈公馆/据点）进行鉴定，获得可装备的基因模组。</li></ul></li><li><p><strong>融合效果</strong>：</p><ul><li>插入【食尸鬼基因】：攻击时有概率吸血。</li><li>插入【蜃楼兽基因】：闪避后短暂隐身。</li><li><strong>基因共鸣 (Resonance)</strong>：如果相邻的两个插槽插入了同类源（如都是“火属性妖兽”），会触发连线共鸣，额外增加属性。</li></ul></li></ul><h3 id="_3-3-基因锁与进化阶级-gene-locks-tiers" tabindex="-1">3.3. 基因锁与进化阶级 (Gene Locks &amp; Tiers) <a class="header-anchor" href="#_3-3-基因锁与进化阶级-gene-locks-tiers" aria-label="Permalink to &quot;3.3. 基因锁与进化阶级 (Gene Locks &amp; Tiers)&quot;">​</a></h3><p>DNA 链被数个**“基因锁”**截断，代表角色的生命层次限制。</p><ul><li><strong>解锁条件</strong>：需随主线剧情推进（获得高纯度娲石）或完成特定的角色支线任务（突破心魔/肉体极限）。</li><li><strong>阶级变化</strong>：打破基因锁后，角色外观会发生微调（如：眼睛变色、皮肤出现纹路、周围伴随蒸汽特效），并解锁下一段 DNA 序列。</li></ul><hr><h2 id="_4-角色差异化设计示例" tabindex="-1">4. 角色差异化设计示例 <a class="header-anchor" href="#_4-角色差异化设计示例" aria-label="Permalink to &quot;4. 角色差异化设计示例&quot;">​</a></h2><h3 id="陈少秋-均衡-雷电" tabindex="-1"><strong>陈少秋 (均衡/雷电)</strong> <a class="header-anchor" href="#陈少秋-均衡-雷电" aria-label="Permalink to &quot;**陈少秋 (均衡/雷电)**&quot;">​</a></h3><ul><li><strong>基因主题</strong>：<strong>雷霆灵枢</strong></li><li><strong>核心强化</strong>： <ul><li><em>神经传导加速</em>：增加攻击速度和暴击。</li><li><em>电荷过载</em>：技能附带麻痹效果。</li></ul></li><li><strong>特殊突变</strong>：【机械共生】—— 允许装备重型蒸汽外骨骼，但无法受到常规治疗技能回复（只能靠修理）。</li></ul><h3 id="林晚晴-医疗-毒素" tabindex="-1"><strong>林晚晴 (医疗/毒素)</strong> <a class="header-anchor" href="#林晚晴-医疗-毒素" aria-label="Permalink to &quot;**林晚晴 (医疗/毒素)**&quot;">​</a></h3><ul><li><strong>基因主题</strong>：<strong>百草神农</strong></li><li><strong>核心强化</strong>： <ul><li><em>细胞再生</em>：强化治疗效果。</li><li><em>毒素中和</em>：自身免疫毒素，并能将毒素转化为能量。</li></ul></li><li><strong>特殊突变</strong>：【以毒攻毒】—— 治疗技能变为对敌方造成持续伤害，切换姿态。</li></ul><h3 id="阿伊莎-炼金-刺客" tabindex="-1"><strong>阿伊莎 (炼金/刺客)</strong> <a class="header-anchor" href="#阿伊莎-炼金-刺客" aria-label="Permalink to &quot;**阿伊莎 (炼金/刺客)**&quot;">​</a></h3><ul><li><strong>基因主题</strong>：<strong>流金之血</strong></li><li><strong>核心强化</strong>： <ul><li><em>液态闪避</em>：极大提高闪避率。</li><li><em>弱点解析</em>：无视敌方部分护甲。</li></ul></li><li><strong>特殊突变</strong>：【完全炼金化】—— 身体可在短时间内金属化，免疫物理伤害，但无法移动。</li></ul><h3 id="朱利安-工程-防御" tabindex="-1"><strong>朱利安 (工程/防御)</strong> <a class="header-anchor" href="#朱利安-工程-防御" aria-label="Permalink to &quot;**朱利安 (工程/防御)**&quot;">​</a></h3><ul><li><strong>基因主题</strong>：<strong>钢铁意志</strong></li><li><strong>核心强化</strong>： <ul><li><em>结构加固</em>：大幅提升血量和负重。</li><li><em>工具精通</em>：道具效果翻倍。</li></ul></li><li><strong>特殊突变</strong>：【多线程大脑】—— 每回合可额外使用一次道具，但精神力消耗加倍。</li></ul><hr><h2 id="_5-资源循环与经济" tabindex="-1">5. 资源循环与经济 <a class="header-anchor" href="#_5-资源循环与经济" aria-label="Permalink to &quot;5. 资源循环与经济&quot;">​</a></h2><ol><li><strong>娲石能量 (Nuwa Energy)</strong>： <ul><li>来源：战斗经验转化（独立于XP）、分解无用基因片段。</li><li>用途：点亮基础节点。</li></ul></li><li><strong>生物样本 (Biological Samples)</strong>： <ul><li>来源：击杀怪物掉落、黑市购买、支线探索。</li><li>用途：解锁关键技能节点、合成高级基因插片。</li></ul></li><li><strong>稳定剂 (Stabilizers)</strong>： <ul><li>来源：炼金制作、商店购买。</li><li>用途：重置基因点数（洗点），消除突变带来的某些副作用。</li></ul></li></ol>',32)])])}const m=o(i,[["render",e]]);export{d as __pageData,m as default};
